import{_ as e,o as a,c as n,a2 as s}from"./chunks/framework.DGu13UIe.js";const g=JSON.parse('{"title":"第 29 课 · 拆开 Agent 与 UI 有什么好处？（扩展阅读）","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/29-agent-split/doc.md"},"headers":[],"relativePath":"chapters/29-agent-split.md","filePath":"chapters/29-agent-split.md"}'),o={name:"chapters/29-agent-split.md"};function d(r,t,l,i,p,c){return a(),n("div",null,[...t[0]||(t[0]=[s(`<h1 id="第-29-课-·-拆开-agent-与-ui-有什么好处-扩展阅读" tabindex="-1">第 29 课 · 拆开 Agent 与 UI 有什么好处？（扩展阅读） <a class="header-anchor" href="#第-29-课-·-拆开-agent-与-ui-有什么好处-扩展阅读" aria-label="Permalink to &quot;第 29 课 · 拆开 Agent 与 UI 有什么好处？（扩展阅读）&quot;">​</a></h1><p><strong>约 25 分钟</strong> · 纯阅读 · <a href="/bagent/chapters/28-agent-network.html">第 28 课</a> 之后</p><p>你在 <a href="/bagent/chapters/28-agent-network.html">第 28 课</a> 已经亲手拆过：<strong>左边 <code>server</code> 跑 Loop，右边 <code>client</code> 只订阅事件</strong>。本课回答：<strong>为什么要费这事？</strong> 以及 <strong>VS Code 插件</strong> 一类产品通常怎么接。</p><hr><h2 id="_1-不拆也能用-为何要拆" tabindex="-1">1. 不拆也能用，为何要拆 <a class="header-anchor" href="#_1-不拆也能用-为何要拆" aria-label="Permalink to &quot;1. 不拆也能用，为何要拆&quot;">​</a></h2><table tabindex="0"><thead><tr><th>阶段</th><th>本课程</th><th>够不够用</th></tr></thead><tbody><tr><td>学习 Loop</td><td><a href="/bagent/chapters/24-agent-loop.html">第 24 课</a> 单进程</td><td>✅ 最少概念</td></tr><tr><td>流式 + 事件</td><td><a href="/bagent/chapters/25-agent-stream.html">第 25–26 课</a></td><td>✅ UI 与内核开始分层</td></tr><tr><td>双进程</td><td><a href="/bagent/chapters/28-agent-network.html">第 28 课</a></td><td>✅ 像「产品雏形」</td></tr></tbody></table><p>单进程不是错——<strong>写课、验证想法、个人脚本</strong> 一直够用。拆进程是为了解决 <strong>界面、安全、协作</strong> 一类问题，而这些在「只做终端 demo」时往往还感觉不到。</p><hr><h2 id="_2-拆开的主要好处" tabindex="-1">2. 拆开的主要好处 <a class="header-anchor" href="#_2-拆开的主要好处" aria-label="Permalink to &quot;2. 拆开的主要好处&quot;">​</a></h2><h3 id="_2-1-换-ui-不改内核" tabindex="-1">2.1 换 UI 不改内核 <a class="header-anchor" href="#_2-1-换-ui-不改内核" aria-label="Permalink to &quot;2.1 换 UI 不改内核&quot;">​</a></h3><p><a href="/bagent/chapters/26-agent-events.html">第 26 课</a> 的 <code>AgentEvent</code> + <a href="/bagent/chapters/28-agent-network.html">第 28 课</a> 的 SSE，本质是同一件事：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>内核只产出事件 → 终端 / 网页 / IDE 各自消费</span></span></code></pre></div><ul><li>今天：终端 <code>client.ts</code> + <code>handleTerminalEvent</code></li><li>明天：React 网页只改订阅端</li><li>后天：VS Code 侧边栏把 <code>ChunkUpdated</code> 画进 Webview</li></ul><p><strong><code>loop.ts</code> / <code>server.ts</code> 可以长期稳定</strong>，UI 随便换皮肤、换交互。</p><h3 id="_2-2-密钥与权限留在「重」的一侧" tabindex="-1">2.2 密钥与权限留在「重」的一侧 <a class="header-anchor" href="#_2-2-密钥与权限留在「重」的一侧" aria-label="Permalink to &quot;2.2 密钥与权限留在「重」的一侧&quot;">​</a></h3><p>第 28 课里：</p><ul><li><strong>server</strong> 持有 <code>DEEPSEEK_API_KEY</code>、<code>history</code>、<code>read_file</code></li><li><strong>client</strong> 只有 <code>fetch localhost:3028</code></li></ul><p>好处：</p><ul><li>UI 进程可以更「轻」、甚至跑在浏览器沙箱里</li><li>少把 Key 散落到每个前端</li><li>工具执行集中在一处，便于 <strong>审批、审计、限路径</strong>（你们 <code>tools.ts</code> 的 <code>allowed</code> 白名单就是雏形）</li></ul><h3 id="_2-3-多个客户端-共用一个-agent" tabindex="-1">2.3 多个客户端，共用一个 Agent <a class="header-anchor" href="#_2-3-多个客户端-共用一个-agent" aria-label="Permalink to &quot;2.3 多个客户端，共用一个 Agent&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>        ┌─ 终端 client.ts</span></span>
<span class="line"><span>server ─┼─ VS Code 插件</span></span>
<span class="line"><span>        └─ 将来的网页控制台</span></span></code></pre></div><p>一个发布端、多个订阅端——适合「团队共用本机 Agent 服务」或「IDE + 脚本并行监控同一 session」（产品里还会加 session id，本课先不展开）。</p><h3 id="_2-4-独立升级与测试" tabindex="-1">2.4 独立升级与测试 <a class="header-anchor" href="#_2-4-独立升级与测试" aria-label="Permalink to &quot;2.4 独立升级与测试&quot;">​</a></h3><table tabindex="0"><thead><tr><th>测什么</th><th>拆开后</th></tr></thead><tbody><tr><td>Loop / 工具逻辑</td><td>只起 server，用 <code>curl -N</code> 打 <code>/chat</code></td></tr><tr><td>UI 渲染</td><td>mock SSE 事件流，不必真调模型</td></tr><tr><td>回归</td><td>事件 JSON 快照对比，比对比整段终端输出稳</td></tr></tbody></table><p>第 26 课若把 <code>terminal.ts</code> 换成 <code>assertEvent()</code>，就是单元测试订阅方，<strong>不必启动 DeepSeek</strong>。</p><h3 id="_2-5-崩溃与卡死隔离" tabindex="-1">2.5 崩溃与卡死隔离 <a class="header-anchor" href="#_2-5-崩溃与卡死隔离" aria-label="Permalink to &quot;2.5 崩溃与卡死隔离&quot;">​</a></h3><ul><li>UI 关窗口：可以只断订阅，server 决定是否保存 <code>history</code></li><li>模型卡住：<code>client</code> 可以超时断开 SSE，server 另做取消（进阶）</li><li>单进程时：一切揉在一起，很难只杀「界面」而不杀「半条 conversation」</li></ul><hr><h2 id="_3-vs-code-插件通常长什么样" tabindex="-1">3. VS Code 插件通常长什么样 <a class="header-anchor" href="#_3-vs-code-插件通常长什么样" aria-label="Permalink to &quot;3. VS Code 插件通常长什么样&quot;">​</a></h2><p>不必先会写插件，先记 <strong>角色分工</strong>（对应你们已写的名字）：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────┐</span></span>
<span class="line"><span>│  VS Code 窗口                            │</span></span>
<span class="line"><span>│  ┌─────────────┐  ┌──────────────────┐  │</span></span>
<span class="line"><span>│  │ 编辑器       │  │ 侧边栏 / Webview   │  │  ← 订阅端（像 client.ts）</span></span>
<span class="line"><span>│  │ 选区、诊断   │  │ 流式字、按钮审批   │  │</span></span>
<span class="line"><span>│  └─────────────┘  └─────────┬────────┘  │</span></span>
<span class="line"><span>│         Extension Host       │ IPC       │</span></span>
<span class="line"><span>└──────────────────────────────│──────────┘</span></span>
<span class="line"><span>                               ▼</span></span>
<span class="line"><span>                    ┌──────────────────────┐</span></span>
<span class="line"><span>                    │ Agent 子进程 / 本地服务  │  ← 发布端（像 server.ts）</span></span>
<span class="line"><span>                    │ Loop、tools、API Key   │</span></span>
<span class="line"><span>                    └──────────────────────┘</span></span></code></pre></div><p>常见接法（由简到繁）：</p><table tabindex="0"><thead><tr><th>接法</th><th>和本课关系</th></tr></thead><tbody><tr><td><strong>HTTP + SSE</strong>（<code>localhost:3028</code>）</td><td>就是 <a href="/bagent/chapters/28-agent-network.html">第 28 课</a>；插件里 <code>fetch</code> 订阅</td></tr><tr><td><strong>stdio + JSON 行</strong></td><td><a href="/bagent/chapters/31-vscode-spawn.html">第 31 课</a>：<code>spawn</code> 子进程，一行一条 <code>AgentEvent</code>；背景见 <a href="/bagent/chapters/17-sse-landscape.html">第 17 课</a></td></tr><tr><td><strong>约定协议（如 ACP）</strong></td><td>编辑器生态的标准化事件名；你们先用自建 <code>AgentEvent</code> 理解原理即可</td></tr></tbody></table><p>插件侧典型工作：</p><ol><li>读用户选中的文件 / 命令面板输入 → 当成 <code>message</code></li><li>订阅事件流 → <code>ChunkUpdated</code> 更新侧边栏</li><li><code>ToolCallStart</code> 时弹「是否允许读某文件」→ 批准后 server 才 <code>runTool</code>（你们尚未实现审批，但架构位在这）</li><li><code>TurnEnd</code> 后把 diff 预览进编辑器</li></ol><p><strong>重点</strong>：插件作者大部分时间写的是 <strong>订阅端 + 编辑器 API</strong>，不是重写 Agent Loop。</p><hr><h2 id="_4-和「全塞在一个进程」比-代价是什么" tabindex="-1">4. 和「全塞在一个进程」比，代价是什么 <a class="header-anchor" href="#_4-和「全塞在一个进程」比-代价是什么" aria-label="Permalink to &quot;4. 和「全塞在一个进程」比，代价是什么&quot;">​</a></h2><p>拆开不是免费午餐：</p><table tabindex="0"><thead><tr><th>代价</th><th>说明</th></tr></thead><tbody><tr><td>部署复杂</td><td>要先起 server，再开 client</td></tr><tr><td>协议要想清楚</td><td>事件类型、版本、断线重连</td></tr><tr><td>调试跨进程</td><td>两边日志要对时间戳</td></tr><tr><td>本机延迟</td><td>多一次 HTTP，通常可忽略</td></tr></tbody></table><p>所以路径是：<strong>先单进程跑通（24）→ 事件化（26）→ 再拆（28）→ 再想插件（本课）</strong>。跳步容易连 Loop 都没稳住就纠结 Webview。</p><hr><h2 id="_5-和你们课程的完整弧线" tabindex="-1">5. 和你们课程的完整弧线 <a class="header-anchor" href="#_5-和你们课程的完整弧线" aria-label="Permalink to &quot;5. 和你们课程的完整弧线&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>24  Loop + history</span></span>
<span class="line"><span>25  流式 SSE（对模型）</span></span>
<span class="line"><span>26  领域事件（对内）</span></span>
<span class="line"><span>27  架构地图（扩展）</span></span>
<span class="line"><span>28  双进程 + SSE 传事件</span></span>
<span class="line"><span>29  本课：为何要拆、插件怎么接</span></span></code></pre></div><p>你截图里 <a href="/bagent/chapters/28-agent-network.html">第 28 课</a> 左右分屏，已经是 <strong>类型 C</strong> 的迷你版。下一步若做 VS Code 插件：<strong>保留 server，把 client 换成 Extension</strong> 即可，事件表不必推倒重来。</p><hr><h2 id="_6-常见误解" tabindex="-1">6. 常见误解 <a class="header-anchor" href="#_6-常见误解" aria-label="Permalink to &quot;6. 常见误解&quot;">​</a></h2><table tabindex="0"><thead><tr><th>误解</th><th>更接近事实</th></tr></thead><tbody><tr><td>「插件 = Agent 全在插件里」</td><td>多数是 <strong>插件 UI + 子进程/服务 Loop</strong></td></tr><tr><td>「拆进程就一定要上云」</td><td>第 28 课全是 <strong>本机两个进程</strong></td></tr><tr><td>「SSE 只能给浏览器」</td><td>Node <code>fetch</code> 一样读流；插件也能用</td></tr><tr><td>「必须先学 VS Code API 才能做 Agent」</td><td>先 <a href="/bagent/chapters/24-agent-loop.html">第 24–28 课</a> 把 Loop 和事件搞懂更划算</td></tr></tbody></table><hr><h2 id="检查点" tabindex="-1">检查点 <a class="header-anchor" href="#检查点" aria-label="Permalink to &quot;检查点&quot;">​</a></h2><ul><li>[ ] 能说出拆开 UI 后，换界面要改哪一侧吗？</li><li>[ ] 能解释为什么 API Key 适合放在 server 吗？</li><li>[ ] 能对照第 28 课说出 VS Code 插件里「订阅端 / 发布端」各是什么吗？</li><li>[ ] 知道拆分的代价（协议、运维）吗？</li></ul><hr><h2 id="下一课" tabindex="-1">下一课 <a class="header-anchor" href="#下一课" aria-label="Permalink to &quot;下一课&quot;">​</a></h2><p><a href="/bagent/chapters/30-vscode-extension.html">第 30 课 · 动手写 VS Code 插件</a> — 订阅 ch28 server 的事件流。</p><p><a href="/bagent/chapters/28-agent-network.html">← 第 28 课</a> · <a href="/bagent/chapters/27-agent-architecture.html">第 27 课 架构</a></p>`,55)])])}const b=e(o,[["render",d]]);export{g as __pageData,b as default};
